try {
  const crypto = require('crypto');

  // Texto ficticio para probar el algoritmo.
  // No lo reemplaces por una contraseña personal.
  const passwordPrueba = 'Solo-Prueba-EventPass-2026!';
  const salt = crypto.randomBytes(16);

  const parametros = {
    N: 131072,
    r: 8,
    p: 1,
    maxmem: 256 * 1024 * 1024,
  };

  const inicio = Date.now();

  // Simulamos el registro.
  const hashRegistro = crypto.scryptSync(
    passwordPrueba,
    salt,
    64,
    parametros
  );

  // Simulamos un login con la contraseña correcta.
  const hashCorrecto = crypto.scryptSync(
    passwordPrueba,
    salt,
    64,
    parametros
  );

  // Simulamos un login con una contraseña incorrecta.
  const hashIncorrecto = crypto.scryptSync(
    'Otra-Clave-De-Prueba',
    salt,
    64,
    parametros
  );

  const aceptaCorrecta = crypto.timingSafeEqual(
    hashRegistro,
    hashCorrecto
  );

  const rechazaIncorrecta = !crypto.timingSafeEqual(
    hashRegistro,
    hashIncorrecto
  );

  // Mostramos solo el resultado, no contraseñas, hashes ni salts.
  return [{
    json: {
      ok: aceptaCorrecta && rechazaIncorrecta,
      algoritmo: 'scrypt',
      salt_bytes: salt.length,
      hash_bytes: hashRegistro.length,
      acepta_password_correcta: aceptaCorrecta,
      rechaza_password_incorrecta: rechazaIncorrecta,
      duracion_total_ms: Date.now() - inicio,
    },
  }];
} catch (error) {
  return [{
    json: {
      ok: false,
      mensaje: 'La prueba criptográfica no pudo completarse.',
      detalle: error.message,
    },
  }];
}
